    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: On a standard ECG recorded at 25 mm/sec, one small box (1 mm) represents how much time?', '["0.02 seconds", "0.04 seconds", "0.10 seconds", "0.20 seconds"]', 1, 'At 25 mm/sec, 1 mm (one small box) equals 0.04 seconds. One large box (5 small boxes) equals 0.20 seconds.'),
    (v_topic_id, '2: What is the standard voltage calibration for a 12-lead ECG?', '["5 mm/mV", "10 mm/mV", "20 mm/mV", "50 mm/mV"]', 1, 'The standard vertical calibration is 10 mm per 1 mV. This means a 1 mV signal produces a 10 mm (two large boxes) deflection.'),
    (v_topic_id, '3: Which lead is considered the most appropriate for observing P-wave morphology?', '["Lead I", "Lead II", "Lead aVL", "Lead V6"]', 1, 'Lead II is parallel to the electrical axis of the atria, providing the best view of the P-wave.'),
    (v_topic_id, '4: To calculate the heart rate from an irregular ECG rhythm (like atrial fibrillation), what is the most accurate method?', '["The 300-150-100 rule", "Count the number of QRS complexes in a 6-second strip and multiply by 10", "Divide 1500 by the number of small boxes between R-waves", "Divide 300 by the number of large boxes between R-waves"]', 1, 'For irregular rhythms, counting the complexes in a 10-second or 6-second rhythm strip is the standard method.'),
    (v_topic_id, '5: A positive QRS complex in Lead I and a negative QRS complex in Lead aVF indicates:', '["Normal Axis", "Left Axis Deviation (LAD)", "Right Axis Deviation (RAD)", "Extreme Axis Deviation"]', 1, 'If Lead I is positive and aVF is negative, the axis is between 0 and -90 degrees, indicating LAD (further confirmed by checking Lead II).'),
    (v_topic_id, '6: A negative QRS complex in Lead I and a positive QRS complex in Lead aVF indicates:', '["Normal Axis", "Left Axis Deviation", "Right Axis Deviation", "Extreme Axis Deviation"]', 2, 'If Lead I is negative and aVF is positive, the axis is between +90 and +180 degrees, indicating RAD.'),
    (v_topic_id, '7: Which of the following is a common cause of Left Axis Deviation (LAD)?', '["Right Ventricular Hypertrophy", "Left Anterior Fascicular Block (LAFB)", "Chronic Obstructive Pulmonary Disease (COPD)", "Lateral Wall MI"]', 1, 'LAFB is one of the most common causes of significant LAD (>-30 degrees).'),
    (v_topic_id, '8: Right Axis Deviation (RAD) is a classic finding in which of the following conditions?', '["Left Ventricular Hypertrophy", "Pulmonary Embolism (Acute Right Heart Strain)", "Inferior Wall MI", "Left Bundle Branch Block"]', 1, 'RAD often results from right-sided pathology, including PE, pulmonary hypertension, and RVH.'),
    (v_topic_id, '9: What is the normal upper limit for the PR interval in an adult?', '["0.10 seconds", "0.12 seconds", "0.20 seconds", "0.24 seconds"]', 2, 'The normal PR interval is 0.12 to 0.20 seconds (3 to 5 small boxes).'),
    (v_topic_id, '10: A PR interval greater than 0.20 seconds defines:', '["First-degree AV block", "Mobitz I (Wenckebach) AV block", "Mobitz II AV block", "Third-degree AV block"]', 0, 'First-degree AV block is defined by a consistent PR interval > 0.20 seconds without dropped QRS complexes.'),
    (v_topic_id, '11: A "P mitrale" morphology (notched, widened P-wave in Lead II and a deep terminal negative deflection in V1) suggests:', '["Right Atrial Enlargement", "Left Atrial Enlargement", "Biatrial Enlargement", "Normal atrial conduction"]', 1, 'P mitrale indicates LAE, often due to mitral stenosis or regurgitation.'),
    (v_topic_id, '12: A "P pulmonale" morphology (tall, peaked P-waves > 2.5 mm in Lead II) suggests:', '["Left Atrial Enlargement", "Right Atrial Enlargement", "Ventricular Tachycardia", "Hypokalemia"]', 1, 'P pulmonale indicates RAE, often seen in chronic lung disease or pulmonary hypertension.'),
    (v_topic_id, '13: What is the normal upper limit for the QRS duration?', '["0.08 seconds", "0.10 seconds", "0.12 seconds", "0.20 seconds"]', 2, 'A normal QRS duration is less than 0.12 seconds (3 small boxes). Values \u2265 0.12 indicate a bundle branch block or ventricular origin.'),
    (v_topic_id, '14: Which ECG criteria are used to diagnose Left Ventricular Hypertrophy (LVH) using the Sokolow-Lyon formula?', '["S in V1 + R in V5 or V6 \u2265 35 mm", "R in I + S in III \u2265 25 mm", "R in aVL \u2265 11 mm", "P-wave duration \u2265 0.12s"]', 0, 'The Sokolow-Lyon criteria for LVH is the sum of S in V1 and R in V5 or V6 \u2265 35 mm.'),
    (v_topic_id, '15: Which finding in Lead aVL is highly suggestive of LVH?', '["R wave amplitude > 5 mm", "R wave amplitude \u2265 11 mm", "Q wave > 1 mm", "T wave inversion"]', 1, 'An R wave \u2265 11 mm in aVL is one of the voltage criteria for LVH.'),
    (v_topic_id, '16: Right Ventricular Hypertrophy (RVH) is typically characterized by which finding in Lead V1?', '["A deep S wave", "An R wave taller than the S wave (R/S ratio > 1)", "A small R wave and large S wave", "ST-segment elevation"]', 1, 'In RVH, the right ventricle becomes dominant, leading to a tall R wave in V1 (where the R/S ratio is normally < 1).'),
    (v_topic_id, '17: What is the significance of "Strain Pattern" (ST depression and T-wave inversion) in the lateral leads (I, aVL, V5, V6)?', '["It indicates acute myocardial infarction", "It is a sign of severe chronic pressure overload, such as in LVH", "It is a normal finding in athletes", "It indicates hyperkalemia"]', 1, 'LVH strain pattern reflects secondary repolarization abnormalities due to severe ventricular hypertrophy.'),
    (v_topic_id, '18: An R-wave in V1 plus an S-wave in V5 or V6 \u2265 10.5 mm is a criteria for:', '["Left Ventricular Hypertrophy", "Right Ventricular Hypertrophy", "Right Bundle Branch Block", "Pericardial Effusion"]', 1, 'This is a common voltage criteria for RVH.'),
    (v_topic_id, '19: Low QRS voltage across all leads (defined as < 5 mm in limb leads and < 10 mm in precordial leads) can be caused by:', '["Left Ventricular Hypertrophy", "Pericardial Effusion or Obesity", "Hyperthyroidism", "High altitude"]', 1, 'Low voltage results from insulation (fluid, air, or fat) between the heart and the electrodes.'),
    (v_topic_id, '20: What is "Electrical Alternans"?', '["A rhythm that alternates between sinus and AFib", "Alternating QRS amplitude from beat to beat", "Alternating PR interval duration", "A sudden shift in the QRS axis"]', 1, 'Electrical alternans (alternating QRS height) is a highly specific sign for massive pericardial effusion and cardiac tamponade as the heart "swings" in fluid.'),
    (v_topic_id, '21: Which ECG lead is directly opposite to V1?', '["Lead V6", "Lead aVF", "Lead I", "Lead III"]', 0, 'V1 and V6 look at the heart from opposite directions (right-side vs. left-side precordium).'),
    (v_topic_id, '22: The "J-point" on an ECG represents:', '["The beginning of the P-wave", "The junction between the end of the QRS and the beginning of the ST segment", "The peak of the T-wave", "The midpoint of the PR interval"]', 1, 'The J-point is the critical reference point used to measure ST-segment elevation or depression.'),
    (v_topic_id, '23: A U-wave, if present, occurs after the T-wave. A prominent U-wave is a classic sign of:', '["Hyperkalemia", "Hypokalemia", "Hypercalcemia", "Hypocalcemia"]', 1, 'Hypokalemia characteristically produces prominent U-waves and flattened T-waves.'),
    (v_topic_id, '24: What is the "Rule of 300" for estimating heart rate?', '["Divide 300 by the number of small boxes between QRS complexes", "Divide 300 by the number of large boxes between QRS complexes", "Multiply the number of QRS complexes by 300", "Divide 300 by the PR interval"]', 1, 'The Rule of 300 (300, 150, 100, 75, 60, 50) uses large boxes to quickly estimate heart rate.'),
    (v_topic_id, '25: The Einthoven Triangle consists of which leads?', '["V1, V2, V3", "I, II, III", "aVR, aVL, aVF", "V4, V5, V6"]', 1, 'Leads I, II, and III are the bipolar limb leads that form the Einthoven Triangle.'),
    (v_topic_id, '26: If Lead I is positive and Lead aVF is positive, the QRS axis is:', '["Left Axis Deviation", "Right Axis Deviation", "Normal (0 to +90 degrees)", "Extreme Deviation"]', 2, 'Two positive "thumbs up" (Leads I and aVF) indicate a normal axis.'),
    (v_topic_id, '27: A patient has a QRS axis of -45 degrees. This is:', '["Normal Axis", "Left Axis Deviation", "Right Axis Deviation", "Extreme Axis Deviation"]', 1, 'LAD is generally defined as an axis between -30 and -90 degrees.'),
    (v_topic_id, '28: What is the Bazett formula used for?', '["Calculating heart rate", "Calculating the corrected QT interval (QTc)", "Measuring QRS voltage", "Estimating cardiac output"]', 1, 'The Bazett formula (QTc = QT / \u221aRR) corrects the QT interval for the heart rate.'),
    (v_topic_id, '29: A normal QTc interval in a male is typically less than:', '["0.36 seconds", "0.40 seconds", "0.44 seconds", "0.50 seconds"]', 2, 'Normal QTc is < 0.44s in males and < 0.46s in females.'),
    (v_topic_id, '30: A prolonged QT interval increases the risk of which life-threatening arrhythmia?', '["Atrial Fibrillation", "Torsades de Pointes", "First-degree AV block", "Bundle Branch Block"]', 1, 'Long QT predisposes to R-on-T phenomenon, triggering the polymorphic ventricular tachycardia known as Torsades de Pointes.'),
    (v_topic_id, '31: Lead aVR is often ignored, but it is useful for diagnosing:', '["Anterior MI", "Lead reversal or Dextrocardia", "RVH", "LBBB"]', 1, 'In Lead aVR, everything (P, QRS, T) should normally be negative. Positive waves in aVR suggest electrode misplacement or dextrocardia.'),
    (v_topic_id, '32: A "W" shape in V1 and an "M" shape in V6 is characteristic of:', '["Right Bundle Branch Block", "Left Bundle Branch Block", "LVH", "Wolff-Parkinson-White"]', 1, 'The mnemonic "WiLLiaM" (W in V1, M in V6) describes the QRS morphology in LBBB.'),
    (v_topic_id, '33: An "M" shape in V1 (rsR'' pattern) and a "W" shape in V6 is characteristic of:', '["Left Bundle Branch Block", "Right Bundle Branch Block", "RVH", "Myocardial Ischemia"]', 1, 'The mnemonic "MaRRoW" (M in V1, W in V6) describes the QRS morphology in RBBB.'),
    (v_topic_id, '34: What is the significance of a "Secondary T-wave inversion" in RBBB?', '["It indicates acute ischemia", "It is a normal repolarization abnormality seen in the right precordial leads (V1-V3)", "It indicates pulmonary embolism", "It suggests digitalis toxicity"]', 1, 'In bundle branch blocks, the T-wave is normally opposite (discordant) to the terminal part of the QRS complex.'),
    (v_topic_id, '35: Bifascicular block usually consists of RBBB plus:', '["First-degree AV block", "Left Anterior Fascicular Block (LAFB) or Left Posterior Fascicular Block (LPFB)", "LVH", "Atrial Fibrillation"]', 1, 'Bifascicular block is the combination of RBBB and a hemiblock (usually LAFB).'),
    (v_topic_id, '36: "Delta waves" and a short PR interval (< 0.12s) are the hallmarks of:', '["Lown-Ganong-Levine syndrome", "Wolff-Parkinson-White (WPW) syndrome", "Hyperkalemia", "Brugada syndrome"]', 1, 'WPW is caused by an accessory pathway (Bundle of Kent) that bypasses the AV node, pre-exciting the ventricles.'),
    (v_topic_id, '37: What is the physiological cause of the PR segment (the flat line after the P-wave)?', '["Atrial depolarization", "Conduction delay in the AV node", "Ventricular repolarization", "Septal depolarization"]', 1, 'The PR segment represents the delay at the AV node, which allows the ventricles to fill with blood before contraction.'),
    (v_topic_id, '38: In an adult, a QRS duration of 0.10 seconds is considered:', '["Narrow (Normal)", "Borderline Widened", "Wide (Bundle Branch Block)", "Severely Prolonged"]', 0, 'Normal QRS is < 0.12s. 0.10s is still within the normal range.'),
    (v_topic_id, '39: A QRS duration of 0.14 seconds indicates:', '["Sinus Tachycardia", "Narrow complex tachycardia", "Wide QRS (likely Bundle Branch Block or Ventricular origin)", "Incomplete Bundle Branch Block"]', 2, 'Any QRS \u2265 0.12s is defined as wide.'),
    (v_topic_id, '40: S-waves in Leads I, II, and III (S1S2S3 pattern) suggests:', '["Left Axis Deviation", "Right Axis Deviation", "Normal Variant or Right Heart Strain", "Hyperkalemia"]', 2, 'The S1S2S3 pattern is a common variant or a sign of right heart strain.'),
    (v_topic_id, '41: Which lead is most likely to show an inverted T-wave as a normal variant in adults?', '["Lead V1", "Lead I", "Lead II", "Lead aVF"]', 0, 'T-wave inversion in V1 (and sometimes V2) can be a normal finding, especially in children or some healthy adults.'),
    (v_topic_id, '42: What is the definition of "Sinus Bradycardia"?', '["Sinus rhythm with a rate < 40 bpm", "Sinus rhythm with a rate < 60 bpm", "Sinus rhythm with an irregular rate", "Sinus rhythm with dropped P-waves"]', 1, 'Sinus bradycardia is a sinus rhythm with a heart rate below 60 beats per minute.'),
    (v_topic_id, '43: What is the definition of "Sinus Tachycardia"?', '["Sinus rhythm with a rate > 80 bpm", "Sinus rhythm with a rate > 100 bpm", "Sinus rhythm with a rate > 150 bpm", "Sinus rhythm with a QRS > 0.12s"]', 1, 'Sinus tachycardia is a sinus rhythm with a heart rate above 100 beats per minute.'),
    (v_topic_id, '44: A P-wave that changes morphology from beat to beat (at least 3 different shapes) with a heart rate < 100 bpm is called:', '["Multifocal Atrial Tachycardia (MAT)", "Wandering Atrial Pacemaker (WAP)", "Atrial Fibrillation", "Sinus Arrhythmia"]', 1, 'WAP is defined by multiple P-wave morphologies at a normal rate. If the rate is > 100, it is called MAT.'),
    (v_topic_id, '45: "Multifocal Atrial Tachycardia" (MAT) is most commonly associated with which underlying condition?', '["Acute MI", "Chronic Obstructive Pulmonary Disease (COPD)", "Hypothyroidism", "Hypercalcemia"]', 1, 'MAT is highly associated with pulmonary disease and hypoxia.'),
    (v_topic_id, '46: In Sinus Arrhythmia, the heart rate increases during _____ and decreases during _____.', '["Expiration, Inspiration", "Inspiration, Expiration", "Exercise, Sleep", "Systole, Diastole"]', 1, 'Sinus arrhythmia is a normal physiological variation where the rate fluctuates with the respiratory cycle.'),
    (v_topic_id, '47: A "Sinus Pause" or "Sinus Arrest" is characterized by:', '["A sudden drop in heart rate to zero", "The failure of the SA node to fire, resulting in a gap on the ECG", "An inverted P-wave", "A shortened PR interval"]', 1, 'Sinus arrest is a failure of SA node impulse generation.'),
    (v_topic_id, '48: If the SA node fails, the AV node usually takes over. The resulting "Junctional Escape Rhythm" typically has a rate of:', '["20-40 bpm", "40-60 bpm", "60-80 bpm", "80-100 bpm"]', 1, 'The intrinsic firing rate of the AV node/junction is 40 to 60 bpm.'),
    (v_topic_id, '49: If both the SA and AV nodes fail, the ventricles may take over. An "Idioventricular Escape Rhythm" typically has a rate of:', '["15-40 bpm", "40-60 bpm", "60-80 bpm", "80-100 bpm"]', 0, 'The intrinsic firing rate of the ventricular pacemakers is very slow, typically 20 to 40 bpm.'),
    (v_topic_id, '50: A junctional rhythm with a heart rate of 85 bpm is called:', '["Sinus Tachycardia", "Junctional Escape Rhythm", "Accelerated Junctional Rhythm", "Junctional Tachycardia"]', 2, 'A junctional rhythm faster than the intrinsic 60 bpm but slower than tachycardia (usually > 100) is called "accelerated."'),
    (v_topic_id, '51: What is the characteristic feature of a "Premature Atrial Contraction" (PAC)?', '["An early QRS without a P-wave", "An early P-wave with a different morphology, followed by a QRS", "A wide QRS complex occurring early", "A long pause followed by a normal beat"]', 1, 'A PAC originates from an ectopic focus in the atria, causing an early P-wave.'),
    (v_topic_id, '52: A "compensatory pause" is most commonly associated with which type of premature beat?', '["PAC", "PVC", "PJC", "Sinus beat"]', 1, 'PVCs usually result in a full compensatory pause, whereas PACs often "reset" the SA node, resulting in a non-compensatory pause.'),
    (v_topic_id, '53: A "Premature Ventricular Contraction" (PVC) is characterized by:', '["An early, narrow QRS complex", "An early, wide and bizarre-looking QRS complex without a preceding P-wave", "A sudden drop in the ST segment", "A notched P-wave"]', 1, 'PVCs originate in the ventricles and do not use the normal conduction system, leading to a slow, wide QRS.'),
    (v_topic_id, '54: "Ventricular Bigeminy" refers to a pattern where:', '["Every other beat is a PVC", "Every third beat is a PVC", "Two PVCs occur in a row", "Three PVCs occur in a row"]', 0, 'In bigeminy, a normal sinus beat alternates with a PVC.'),
    (v_topic_id, '55: "Ventricular Trigeminy" refers to a pattern where:', '["Every other beat is a PVC", "Every third beat is a PVC (two sinus beats, one PVC)", "Three PVCs occur in a row", "A PVC is followed by two sinus beats"]', 1, 'In trigeminy, a PVC occurs after every two normal beats.'),
    (v_topic_id, '56: Two consecutive PVCs are called a:', '["Triplet", "Couple", "Couplet", "Run of VT"]', 2, 'Two PVCs in a row form a couplet.'),
    (v_topic_id, '57: Three or more consecutive PVCs at a rate > 100 bpm define:', '["Ventricular Couplet", "Ventricular Tachycardia (VT)", "Ventricular Fibrillation (VF)", "Accelerated Idioventricular Rhythm"]', 1, 'VT is defined as 3 or more PVCs in a row at a fast rate.'),
    (v_topic_id, '58: What is the definition of "Nonsustained Ventricular Tachycardia" (NSVT)?', '["VT lasting < 10 seconds", "VT lasting < 30 seconds", "VT that causes syncope", "VT that occurs during sleep"]', 1, 'NSVT is defined as lasting at least 3 beats but less than 30 seconds.'),
    (v_topic_id, '59: "Monomorphic VT" means:', '["The QRS complexes all look the same", "The rate varies significantly", "The axis shifts constantly", "There are multiple P-wave shapes"]', 0, 'In monomorphic VT, every QRS complex looks identical because they all originate from the same ectopic focus.'),
    (v_topic_id, '60: "Polymorphic VT" (including Torsades de Pointes) is characterized by:', '["Identical QRS complexes", "QRS complexes that change morphology and axis continuously", "A very slow heart rate", "Narrow QRS complexes"]', 1, 'Polymorphic VT involves multiple foci or a shifting electrical circuit, leading to varying QRS shapes.'),
    (v_topic_id, '61: A PVC that occurs on the peak of the preceding T-wave is dangerous because it can trigger VT/VF. This is called:', '["R-on-P phenomenon", "R-on-T phenomenon", "Ashman phenomenon", "Wenckebach phenomenon"]', 1, 'The "vulnerable period" of the T-wave (repolarization) is a high-risk time for an ectopic beat to trigger a re-entrant arrhythmia.'),
    (v_topic_id, '62: In First-degree AV block, the relationship between P-waves and QRS complexes is:', '["One P-wave for every QRS, with a constant, prolonged PR interval", "More P-waves than QRS complexes", "No relationship between P and QRS", "Shortened PR intervals"]', 0, 'Every P-wave is conducted, but there is a fixed delay.'),
    (v_topic_id, '63: Mobitz Type I (Wenckebach) AV block is characterized by:', '["Progressive shortening of the PR interval until a beat is dropped", "Progressive lengthening of the PR interval until a QRS is dropped", "A fixed, prolonged PR interval with occasional dropped beats", "Complete dissociation between atria and ventricles"]', 1, 'Wenckebach is "Longer, Longer, Longer, Drop!"'),
    (v_topic_id, '64: Mobitz Type II AV block is characterized by:', '["Progressive lengthening of the PR interval", "A fixed PR interval followed by a sudden, unexpected dropped QRS", "An irregular sinus rhythm", "Dropped P-waves"]', 1, 'In Mobitz II, the PR interval of the conducted beats is constant, but some P-waves fail to conduct to the ventricles.'),
    (v_topic_id, '65: Which type of second-degree AV block is almost always located in the AV node and is usually benign?', '["Mobitz Type I (Wenckebach)", "Mobitz Type II", "2:1 AV block", "High-grade AV block"]', 0, 'Wenckebach usually occurs in the AV node itself and is often reversible (e.g., with increased vagal tone).'),
    (v_topic_id, '66: Which type of second-degree AV block is almost always infra-nodal (in the His-Purkinje system) and has a high risk of progressing to complete heart block?', '["Mobitz Type I", "Mobitz Type II", "First-degree AV block", "Sinus Bradycardia"]', 1, 'Mobitz II is much more serious and often requires a permanent pacemaker.'),
    (v_topic_id, '67: Third-degree (Complete) AV block is defined by:', '["A very long PR interval", "Occasional dropped QRS complexes", "Total dissociation between P-waves and QRS complexes", "A QRS duration > 0.12s"]', 2, 'No atrial impulses reach the ventricles; the atria and ventricles beat independently.'),
    (v_topic_id, '68: In Third-degree AV block, the ventricular rate is typically _____ than the atrial rate.', '["Faster", "Slower", "The same", "Irregular"]', 1, 'The ventricular escape rhythm is always slower than the sinus atrial rate.'),
    (v_topic_id, '69: A "high-grade" AV block refers to:', '["First-degree block", "A 2:1 or 3:1 AV conduction ratio", "Third-degree block", "RBBB"]', 1, 'High-grade block is a form of 2nd-degree block where many P-waves fail to conduct.'),
    (v_topic_id, '70: What happens to the QRS complex in Third-degree AV block if the escape pacemaker is located in the AV junction?', '["It is narrow (< 0.12s)", "It is wide (> 0.12s)", "It disappears", "It becomes notched"]', 0, 'Junctional escape rhythms have narrow QRS complexes because they use the normal ventricular conduction system.'),
    (v_topic_id, '71: What happens to the QRS complex in Third-degree AV block if the escape pacemaker is located in the ventricles?', '["It is narrow", "It is wide (> 0.12s)", "It is very fast (> 100 bpm)", "It is inverted"]', 1, 'Ventricular escape rhythms are wide and slow.'),
    (v_topic_id, '72: "Capture beats" and "Fusion beats" are hallmarks of which arrhythmia when seen in the context of a wide-complex tachycardia?', '["SVT with aberrancy", "Ventricular Tachycardia (VT)", "Atrial Fibrillation", "WPW syndrome"]', 1, 'Capture and fusion beats prove AV dissociation, which is diagnostic for VT.'),
    (v_topic_id, '73: A "Fusion beat" occurs when:', '["Two P-waves merge", "A sinus impulse and a ventricular impulse simultaneously depolarize the ventricles", "A PVC and a PAC occur together", "The T-wave and P-wave merge"]', 1, 'The resulting QRS complex has a hybrid morphology between a normal beat and a PVC.'),
    (v_topic_id, '74: A "Capture beat" occurs when:', '["The SA node is captured by the AV node", "A sinus impulse happens to find the conduction system non-refractory and produces a normal-looking beat during VT", "The heart stops", "The baseline becomes flat"]', 1, 'This is evidence that the atria are still functioning independently of the ventricles.'),
    (v_topic_id, '75: Atrial Fibrillation is best described as:', '["Regularly irregular with sawtooth waves", "Irregularly irregular without discernible P-waves", "Regularly irregular with notched P-waves", "Regular with wide QRS complexes"]', 1, 'AFib is the classic "irregularly irregular" rhythm with a chaotic baseline.'),
    (v_topic_id, '76: The atrial rate in Atrial Fibrillation is typically:', '["60-100 bpm", "150-250 bpm", "350-600 bpm", "100-150 bpm"]', 2, 'The atria are not contracting, but rather "quivering" at very high frequencies.'),
    (v_topic_id, '77: Atrial Flutter is characterized by:', '["Chaotic baseline", "Sawtooth-shaped \"F\" waves best seen in Leads II, III, and aVF", "Inverted P-waves in Lead I", "Wide QRS complexes"]', 1, 'Atrial flutter is caused by a large macro-reentrant circuit, usually in the right atrium.'),
    (v_topic_id, '78: The atrial rate in Atrial Flutter is classically:', '["150 bpm", "250 bpm", "300 bpm", "450 bpm"]', 2, 'The atrial rate is very consistently around 300 bpm, often with 2:1 or 3:1 AV conduction resulting in ventricular rates of 150 or 100 bpm.'),
    (v_topic_id, '79: "Ashman Phenomenon" refers to:', '["A PVC following a long PR interval", "A wide QRS complex (aberrancy) that occurs when a short cycle follows a long cycle", "A sudden drop in heart rate", "Electrical alternans"]', 1, 'This is commonly seen in AFib and can be mistaken for a PVC.'),
    (v_topic_id, '80: Paroxysmal Supraventricular Tachycardia (PSVT) is most commonly caused by:', '["Atrial Fibrillation", "AV Nodal Re-entrant Tachycardia (AVNRT)", "Ventricular Fibrillation", "Sinus Arrhythmia"]', 1, 'AVNRT uses a small re-entrant circuit within the AV node itself.'),
    (v_topic_id, '81: In AVNRT, the P-waves are usually:', '["Tall and peaked", "Notched", "Inverted and often buried within or immediately after the QRS", "Absent"]', 2, 'Because the atria are depolarized from the bottom up (retrograde), the P-waves are inverted and occur very close to the QRS.'),
    (v_topic_id, '82: Which maneuver can be used to help terminate or slow down an SVT to reveal the underlying rhythm?', '["Coughing", "Valsalva maneuver or Carotid sinus massage", "Standing up quickly", "Deep breathing"]', 1, 'Vagal maneuvers increase the refractory period of the AV node, potentially breaking a re-entrant circuit.'),
    (v_topic_id, '83: "Sick Sinus Syndrome" (SSS) is characterized by:', '["A consistently fast heart rate", "Periods of sinus bradycardia, sinus arrest, and alternating tachyarrhythmias (Tachy-Brady syndrome)", "Complete heart block", "Delta waves"]', 1, 'SSS is a dysfunction of the SA node, often seen in the elderly.'),
    (v_topic_id, '84: In a patient with Wolff-Parkinson-White (WPW) syndrome, what happens to the PR interval?', '["It is prolonged", "It is shortened (< 0.12s)", "It is normal", "It disappears"]', 1, 'The bypass tract conducts faster than the AV node, leading to a short PR interval.'),
    (v_topic_id, '85: The slurred upstroke of the QRS in WPW is called a:', '["J-wave", "Delta wave", "U-wave", "Osborne wave"]', 1, 'The delta wave represents early, slow ventricular depolarization through the bypass tract.'),
    (v_topic_id, '86: Why is Atrial Fibrillation dangerous in a patient with WPW?', '["It causes heart block", "Impulses can conduct 1:1 down the bypass tract, leading to extremely fast ventricular rates and potentially VF", "It makes the heart too slow", "It causes the bypass tract to disappear"]', 1, 'The bypass tract lacks the "gatekeeping" delay of the AV node, which can lead to life-threateningly fast rates.'),
    (v_topic_id, '87: "Left Anterior Fascicular Block" (LAFB) is characterized by:', '["Right Axis Deviation", "Left Axis Deviation (>-45 degrees) with small Q in I and small S in III", "Wide QRS > 0.12s", "Notched P-waves"]', 1, 'LAFB is a common cause of LAD where the QRS duration is usually normal or only slightly prolonged.'),
    (v_topic_id, '88: "Left Posterior Fascicular Block" (LPFB) is characterized by:', '["Left Axis Deviation", "Right Axis Deviation in the absence of RVH or lateral MI", "Prolonged PR interval", "ST elevation in V1-V3"]', 1, 'LPFB is much rarer than LAFB and causes RAD.'),
    (v_topic_id, '89: A "Trifascicular Block" traditionally consists of a bifascicular block plus:', '["Atrial Fibrillation", "First-degree AV block", "LVH", "RVH"]', 1, 'This suggests significant disease in all three conduction pathways (RBBB, one of the left fascicles, and the remaining fascicle is delayed).'),
    (v_topic_id, '90: In a 12-lead ECG, which leads are considered "Inferior"?', '["I, aVL, V5, V6", "V1, V2, V3, V4", "II, III, aVF", "aVR, aVL"]', 2, 'Leads II, III, and aVF look at the heart from below.'),
    (v_topic_id, '91: In a 12-lead ECG, which leads are considered "Lateral"?', '["II, III, aVF", "I, aVL, V5, V6", "V1, V2", "V3, V4"]', 1, 'These leads look at the left side (lateral wall) of the heart.'),
    (v_topic_id, '92: In a 12-lead ECG, which leads are considered "Septal"?', '["V1, V2", "V3, V4", "V5, V6", "I, aVL"]', 0, 'V1 and V2 are positioned over the interventricular septum.'),
    (v_topic_id, '93: In a 12-lead ECG, which leads are considered "Anterior"?', '["V1, V2", "V3, V4", "V5, V6", "II, III, aVF"]', 1, 'V3 and V4 are positioned over the anterior wall of the left ventricle.'),
    (v_topic_id, '94: Precordial leads (V1-V6) observe the heart in the _____ plane.', '["Frontal", "Horizontal", "Sagittal", "Coronal"]', 1, 'The chest leads provide a horizontal view of cardiac electrical activity.'),
    (v_topic_id, '95: Limb leads (I, II, III, aVR, aVL, aVF) observe the heart in the _____ plane.', '["Frontal", "Horizontal", "Sagittal", "Transverse"]', 0, 'The limb leads provide a frontal (coronal) view.'),
    (v_topic_id, '96: "Normal R-wave progression" across the precordial leads is characterized by:', '["R-wave getting smaller from V1 to V6", "R-wave getting taller and S-wave getting shallower from V1 to V6", "Consistent QRS height in all leads", "R-waves being tall in V1 and V2 only"]', 1, 'The R-wave should gradually increase in height, and the S-wave should decrease, as the leads move from the right ventricle toward the left ventricle.'),
    (v_topic_id, '97: "Poor R-wave progression" (low R-waves through V3 or V4) is a non-specific finding but can suggest:', '["Old Anterior MI", "RVH", "Left Axis Deviation", "Normal variant"]', 0, 'It often indicates a loss of anterior forces due to an old infarction.'),
    (v_topic_id, '98: In Lead I, the right arm electrode is _____ and the left arm electrode is _____.', '["Positive, Negative", "Negative, Positive", "Neutral, Positive", "Positive, Neutral"]', 1, 'Lead I measures the potential difference between the left arm (+) and the right arm (-).'),
    (v_topic_id, '99: In Lead aVF, the exploratory electrode is on the:', '["Right Arm", "Left Arm", "Left Foot", "Right Foot"]', 2, 'aVF stands for augmented Vector Foot.'),
    (v_topic_id, '100: "Dextrocardia" would most classically show which finding on a 12-lead ECG?', '["Left Axis Deviation", "Global negativity in Lead I (inverted P, QRS, and T)", "Tall R waves in V5 and V6", "S1Q3T3 pattern"]', 1, 'Since the heart is on the right, the electrical vectors point away from Lead I, causing everything to be inverted.');
